  en: { title: 'Layout', lead: 'Layout makes Volt materials easy to grasp and prevents them from feeling like random assembled parts.', guidelines: [{ title: 'One Focus', text: 'Every material needs one clear main message. Everything else supports it.' }, { title: 'Enough Spacing', text: 'Logo, headline, text and CTA need room. Density comes from order, not crowding.' }, { title: 'Repetition', text: 'Grids, colours, font sizes and stripes should be used consistently.' }], sections: { rules: { id: 'version-1-rules', title: 'Version 1 Rules', items: ['Basic principles for simple, quickly understandable design.', 'Examples for posters, social media, websites and presentations.', 'Rules for whitespace, focus and text volume.', 'Notes for mobile and accessible display.'] }, spacing: { id: 'spacing', title: 'Spacing', items: ['Spacing should show relationships: tighter for related elements, larger for new topics.', 'Keep padding in cards, buttons and forms consistent.', 'On small screens, stack content rather than shrinking spacing until hierarchy disappears.', 'For version 1, spacing rules are editorial; later component rules can define concrete values.'] }, orientation: { id: 'practical-orientation', title: 'Practical Orientation', items: ['Poster: large headline, clear visual, short supporting information.', 'Social media: strong first line, little text, recognisable Volt colour.', 'Website: scannable sections, enough contrast, no wall of text.', 'Presentation: one statement per slide, large typography, little detail text.'] } } },
  nl: { title: 'Lay-out', lead: 'Lay-out zorgt ervoor dat Volt-materialen snel begrijpelijk zijn en niet als willekeurige losse onderdelen aanvoelen.', guidelines: [{ title: 'Één Focus', text: 'Elk materiaal heeft één duidelijke hoofdboodschap nodig. Alles daarbuiten ondersteunt die boodschap.' }, { title: 'Genoeg Afstand', text: 'Logo, kop, tekst en CTA hebben ruimte nodig. Dichtheid ontstaat door ordening, niet door krapte.' }, { title: 'Herhaling', text: 'Rasters, kleuren, lettergroottes en strepen moeten terugkerend worden gebruikt.' }], sections: { rules: { id: 'versie-1-regels', title: 'Versie 1-regels', items: ['Basisprincipes voor eenvoudige en snel begrijpelijke vormgeving.', 'Voorbeelden voor poster, social media, website en presentatie.', 'Regels voor witruimte, focus en hoeveelheid tekst.', 'Aanwijzingen voor mobiele en toegankelijke weergave.'] }, spacing: { id: 'spacings', title: 'Spacings', items: ['Afstanden moeten relaties tonen: dichter bij elkaar voor elementen die samen horen, ruimer voor nieuwe thema’s.', 'Binnenruimte in kaarten, knoppen en formulieren consistent houden.', 'Op kleine schermen liever stapelen dan afstanden zo verkleinen dat de hiërarchie verdwijnt.', 'Voor versie 1 zijn spacing-regels redactioneel; latere componentregels kunnen concrete waarden vastleggen.'] }, orientation: { id: 'praktische-orientatie', title: 'Praktische Oriëntatie', items: ['Poster: grote kop, duidelijk beeld, korte extra informatie.', 'Social media: sterke eerste regel, weinig tekst, herkenbare Volt-kleur.', 'Website: scanbare secties, genoeg contrast, geen tekstmuur.', 'Presentatie: één boodschap per slide, grote typografie, weinig detailtekst.'] } } },
