  de: { title: 'Bildsprache', lead: 'Dieses Kapitel sammelt Regeln für Fotos, Illustrationen und Beispielmaterial. Gute Bildsprache macht Volt politisch, nahbar und glaubwürdig sichtbar.', guidelines: [{ title: 'Menschen zeigen', text: 'Fotos sollen echte Aktivität, Begegnung und politische Arbeit zeigen, nicht nur Symbolbilder.' }, { title: 'Lesbarkeit schützen', text: 'Text nicht auf unruhige Bildbereiche setzen. Bei Bedarf Flächen, Verlauf oder ausreichend Abstand nutzen.' }, { title: 'Rechte klären', text: 'Nur Bilder verwenden, für die Nutzungsrechte, Einverständnisse und Quellen geklärt sind.' }], doText: 'Nutze helle, klare Motive mit erkennbarer Handlung und genug Raum für Text.', dontText: 'Nutze keine beliebigen Stockbilder, unvorteilhaften Zuschnitte oder Bilder mit unklaren Rechten.', sections: { sources: { id: 'bildquellen', title: 'Bildquellen', items: ['Eigene Fotos und freigegebene Team-Bilder bevorzugen.', 'Bei Personen erkennbare Einwilligung, Kontext und Nutzungsdauer klären.', 'Stockbilder nur nutzen, wenn Lizenz, Quelle und politischer Kontext eindeutig passen.', 'Quelle, Lizenz, Freigabe und Bearbeitungsstand zusammen mit der Datei dokumentieren.'] }, clarify: { id: 'redaktionell-offen', title: 'Redaktionell offen', items: ['Welche Motive passen zu Volt?', 'Welche Bildrechte müssen Teams beachten?', 'Wie werden Menschen, Orte und Aktionen respektvoll gezeigt?', 'Welche Anforderungen gelten für Kontrast, Lesbarkeit und Barrierefreiheit?'] }, storage: { id: 'ablage', title: 'Ablage', text: 'Beispielbilder liegen später in public/brand/examples/.' } } },
  en: { title: 'Image Language', lead: 'This chapter collects rules for photos, illustrations and example material. Good image language makes Volt visible as political, approachable and credible.', guidelines: [{ title: 'Show People', text: 'Photos should show real activity, encounters and political work, not only symbolic images.' }, { title: 'Protect Readability', text: 'Do not place text on busy image areas. Use surfaces, gradients or enough spacing when needed.' }, { title: 'Clarify Rights', text: 'Only use images where usage rights, consent and sources are clear.' }], doText: 'Use bright, clear motifs with recognisable action and enough room for text.', dontText: 'Do not use generic stock images, awkward crops or images with unclear rights.', sections: { sources: { id: 'image-sources', title: 'Image Sources', items: ['Prefer own photos and approved team images.', 'For recognisable people, clarify consent, context and duration of use.', 'Use stock images only when licence, source and political context clearly fit.', 'Document source, licence, approval and edit status together with the file.'] }, clarify: { id: 'editorial-open', title: 'Editorially Open', items: ['Which motifs fit Volt?', 'Which image rights do teams need to consider?', 'How are people, places and actions shown respectfully?', 'Which requirements apply to contrast, readability and accessibility?'] }, storage: { id: 'storage', title: 'Storage', text: 'Example images will later live in public/brand/examples/.' } } },
  nl: { title: 'Beeldtaal', lead: 'Dit hoofdstuk verzamelt regels voor foto’s, illustraties en voorbeeldmateriaal. Goede beeldtaal maakt Volt politiek, benaderbaar en geloofwaardig zichtbaar.', guidelines: [{ title: 'Mensen Tonen', text: 'Foto’s moeten echte activiteit, ontmoeting en politiek werk tonen, niet alleen symboolbeelden.' }, { title: 'Leesbaarheid Beschermen', text: 'Plaats tekst niet op drukke beelddelen. Gebruik indien nodig vlakken, verloop of voldoende afstand.' }, { title: 'Rechten Duidelijk Maken', text: 'Gebruik alleen beelden waarvan gebruiksrechten, toestemming en bronnen duidelijk zijn.' }], doText: 'Gebruik lichte, duidelijke beelden met herkenbare handeling en genoeg ruimte voor tekst.', dontText: 'Gebruik geen willekeurige stockbeelden, ongunstige uitsneden of beelden met onduidelijke rechten.', sections: { sources: { id: 'beeldbronnen', title: 'Beeldbronnen', items: ['Geef voorkeur aan eigen foto’s en goedgekeurde teambeelden.', 'Bij herkenbare personen toestemming, context en gebruiksduur verduidelijken.', 'Stockbeelden alleen gebruiken als licentie, bron en politieke context duidelijk passen.', 'Bron, licentie, goedkeuring en bewerkingsstatus samen met het bestand documenteren.'] }, clarify: { id: 'te-verduidelijken', title: 'Te Verduidelijken', items: ['Welke motieven passen bij Volt?', 'Op welke beeldrechten moeten teams letten?', 'Hoe worden mensen, plaatsen en acties respectvol getoond?', 'Welke eisen gelden voor contrast, leesbaarheid en toegankelijkheid?'] }, storage: { id: 'opslag', title: 'Opslag', text: 'Voorbeeldbeelden komen later in public/brand/examples/.' } } },
